/*
 * prog48_sorted_linked_list
 *
 * The original binary builds a sorted singly‑linked list from the command line
 * arguments (interpreted as decimal integers) and then prints the list.
 * If no numbers are supplied it prints the literal string "EMPTY".
 *
 * The implementation below reproduces the observable behaviour of the
 * original program – the exact control‑flow obfuscation is not required.
 *
 * Behaviour:
 *   • All arguments after the program name are parsed with `strtol` (base 10).
 *   • The numbers are inserted into a singly‑linked list that is kept in
 *     non‑decreasing order (duplicates are allowed and appear after earlier
 *     duplicates).
 *   • After all numbers are processed the list is printed:
 *         <value0> <value1> … <valueN>\n
 *     (a single space separates values, no trailing space).
 *   • If no arguments are given the program prints:
 *         EMPTY\n
 * The original binary limited the list to 64 elements; this implementation
 * follows the same limit – any additional arguments are ignored.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_ELEMS 64          /* maximum number of values the list can hold */

static long  value[MAX_ELEMS];   /* stored numbers */
static int   next[MAX_ELEMS];   /* index of the next node, -1 = end */
static int   head = -1;         /* index of the first node, -1 = empty */
static int   used = 0;          /* number of nodes currently in the list */

/* Insert `v` into the list keeping it sorted in non‑decreasing order. */
static void insert_sorted(long v)
{
    int new_idx = used;          /* index of the node we are about to add */
    value[new_idx] = v;
    next[new_idx]  = -1;         /* will be set properly below */

    /* Empty list – new node becomes the head */
    if (head == -1) {
        head = new_idx;
        return;
    }

    /* Insert before the current head if it is larger than the new value */
    if (value[head] > v) {
        next[new_idx] = head;
        head = new_idx;
        return;
    }

    /* Walk the list to find the insertion point.
       `prev` points to the node after which the new node will be linked. */
    int prev = head;
    while (next[prev] != -1 && value[next[prev]] <= v) {
        prev = next[prev];
    }

    /* Insert after `prev` */
    next[new_idx] = next[prev];
    next[prev]   = new_idx;
}

/* Print the list in the required format. */
static void print_list(void)
{
    if (head == -1) {
        puts("EMPTY");
        return;
    }

    int cur   = head;
    int first = 1;
    while (cur != -1) {
        if (first) {
            printf("%ld", value[cur]);
            first = 0;
        } else {
            printf(" %ld", value[cur]);
        }
        cur = next[cur];
    }
    putchar('\n');
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* Initialise global state (mirrors the original binary). */
    head = -1;
    used = 0;

    /* No numbers supplied → just print "EMPTY". */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    /* Process each command‑line argument (up to MAX_ELEMS). */
    for (int i = 1; i < argc && used < MAX_ELEMS; ++i) {
        char *endptr = NULL;
        long  v = strtol(argv[i], &endptr, 10);

        /* The original program ignored conversion errors; we do the same. */
        (void)endptr;   /* silence unused‑variable warning */

        insert_sorted(v);
        ++used;
    }

    /* Output the resulting list. */
    print_list();
    return 0;
}
